    bindLeadRows();$$('[data-stage-open]').forEach(button=>button.onclick=()=>{state.stage=button.dataset.stageOpen;state.q='';state.fit='';state.dnc='';state.complete='';state.capital='';state.offset=0;navigate('directory');});
